// pages/_app.tsx (старое, работало годами)
Router.events.on('routeChangeStart', () => NProgress.start());
Router.events.on('routeChangeComplete', () => NProgress.done());

App-роутер полностью удалил глобальный эмиттер ___b1___. usePathname и useSearchParams обновляются только ___b2___ коммита навигации, поэтому сигнала старта не существует; реалистичная замена — обернуть ___b3___ (и программные push) для эмиссии собственного старта либо принять посегментный loading.tsx.
